<script>const items=<?=json_encode($items,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;let n=0;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function addRow(){const i=n++,row=document.createElement('div');row.className='border rounded-xl p-4 bg-gray-50';const opts=items.map(x=>`<option value="${x.id}">${esc(x.nama)}</option>`).join('');row.innerHTML=`<div class="grid md:grid-cols-12 gap-3 items-end"><div class="md:col-span-3"><label class="block text-xs font-semibold mb-1">Sumber</label><select name="source_types[${i}]" class="source w-full border rounded-lg px-3 py-2"><option value="STOCK">Dari Stok</option><option value="MANUAL">Manual / Custom</option></select></div><div class="md:col-span-5"><label class="block text-xs font-semibold mb-1">Barang</label><select name="item_ids[${i}]" class="item w-full border rounded-lg px-3 py-2"><option value="">Pilih Barang</option>${opts}</select><input name="manual_names[${i}]" class="manual hidden w-full border rounded-lg px-3 py-2" placeholder="Nama barang custom"></div><div class="md:col-span-2"><label class="block text-xs font-semibold mb-1">Jumlah Diminta</label><input type="number" name="quantities[${i}]" value="1" min="1" class="w-full border rounded-lg px-3 py-2 text-center"></div><div class="md:col-span-2 text-right"><button type="button" class="text-red-500 font-semibold" onclick="this.closest('.border').remove()">Hapus</button></div></div>`;document.getElementById('body').appendChild(row);const s=row.querySelector('.source'),it=row.querySelector('.item'),manual=row.querySelector('.manual');const sync=()=>{if(s.value==='MANUAL'){it.classList.add('hidden');it.removeAttribute('required');manual.classList.remove('hidden');manual.setAttribute('required','required');}else{it.classList.remove('hidden');it.setAttribute('required','required');manual.classList.add('hidden');manual.removeAttribute('required');}};s.addEventListener('change',sync);sync();}addRow();</script>
